-- 5. BOOK_REVIEWS — 80 đánh giá đa dạng
-- ═══════════════════════════════════════════════════════════════════════
INSERT INTO book_reviews (book_id, user_id, rating, comment, is_hidden) VALUES
(1,  2,  5, 'Tuyệt vời! Gắn liền với ký ức tuổi thơ của tôi. Văn phong Tô Hoài rất sinh động và đầy màu sắc.', 0),
(1,  3,  4, 'Đọc rất lôi cuốn, thích cách kể chuyện hấp dẫn của tác giả. Dế Mèn là nhân vật không thể quên.', 0),
(1,  4,  5, 'Kiệt tác văn học thiếu nhi Việt Nam. Con tôi cũng đọc và cũng rất thích!', 0),
(2,  5,  4, 'Tô Hoài viết hay, phản ánh chân thực cuộc sống người dân tộc thiểu số thời bấy giờ.', 0),
(3,  2,  5, 'Phản ánh chân thực cuộc sống nông dân. Đây là tác phẩm phải đọc với ai học văn!', 0),
(3,  6,  4, 'Ngô Tất Tố viết rất sắc sảo. Cảnh chị Dậu bán con đọc mà nghẹn ngào.', 0),
(4,  7,  3, 'Hay nhưng châm biếm hơi nặng, cần đọc kỹ mới hiểu hết ý nghĩa.', 0),
