-- 6. ANNOUNCEMENTS — 20 thông báo sự kiện
-- ═══════════════════════════════════════════════════════════════════════
INSERT INTO announcements (title, content, type, start_date, end_date, is_active, created_by) VALUES
('Thư viện mở cửa xuyên hè 2026',          'Thư viện HCMUE phục vụ bạn đọc xuyên suốt mùa hè từ 7:30–21:00 tất cả các ngày kể cả thứ 7, Chủ nhật.', 'general', '2026-06-01', '2026-08-31', 1, 1),
('Cuộc thi đọc sách tháng 6',              'Tham gia cuộc thi đọc sách tháng 6 để nhận nhiều phần thưởng hấp dẫn! Giải nhất: thẻ thư viện VIP 1 năm. Đăng ký tại quầy thư viện trước 31/5.', 'contest', '2026-06-01', '2026-06-30', 1, 1),
('Nghỉ lễ Quốc khánh 2/9',                'Thư viện thông báo lịch nghỉ lễ Quốc khánh từ 02/09/2026 đến hết ngày 03/09/2026. Gia hạn sách tự động 2 ngày.', 'holiday', '2026-09-02', '2026-09-03', 1, 1),
('Bổ sung 200 đầu sách mới tháng 5/2026', 'Thư viện vừa nhập thêm 200 đầu sách mới đa thể loại: CNTT, Kỹ năng sống, Văn học, Y học và Khoa học. Mời bạn đọc vào xem và mượn.', 'general', '2026-05-01', '2026-05-31', 1, 1),
('Triển lãm sách tháng 5',                 'Triển lãm "Sách và Cuộc sống" diễn ra từ 15-20/5/2026 tại sảnh thư viện tầng 1. Có nhiều hoạt động giao lưu và tặng sách.', 'event', '2026-05-15', '2026-05-20', 1, 1),
('Hội thảo kỹ năng đọc sách hiệu quả',   'Hội thảo "Đọc sách thông minh — Học tập hiệu quả" do TS. Nguyễn Văn X trình bày. Thời gian: 14:00 ngày 18/5/2026.', 'event', '2026-05-18', '2026-05-18', 1, 1),
('Gia hạn thời gian mượn sách mùa thi',   'Trong mùa thi học kỳ 2 (1/6–30/6/2026), thời hạn mượn sách được gia hạn tự động thêm 7 ngày cho tất cả sinh viên.', 'general', '2026-06-01', '2026-06-30', 1, 1),
('Thông báo bảo trì hệ thống',             'Hệ thống thư viện trực tuyến sẽ bảo trì từ 23:00 ngày 30/5 đến 05:00 ngày 31/5/2026. Xin lỗi vì sự bất tiện này.', 'general', '2026-05-30', '2026-05-31', 1, 1),
('Cuộc thi viết cảm nhận sách hè 2026',   'Viết cảm nhận về cuốn sách yêu thích trong hè 2026, gửi qua email library@hcmue.edu.vn để có cơ hội nhận phần thưởng hấp dẫn.', 'contest', '2026-07-01', '2026-08-15', 1, 1),
('Khai mạc CLB Sách và Trà',              'CLB Sách và Trà chính thức ra mắt! Sinh hoạt mỗi thứ 6 tuần đầu tháng, 9:00-11:00, tại phòng đọc tầng 2. Mời bạn đọc tham gia.', 'event', '2026-06-05', '2026-12-31', 1, 1),
('Thư viện số HCMUE ra mắt',              'Thư viện số HCMUE chính thức ra mắt! Truy cập hàng nghìn tài liệu điện tử miễn phí tại digital.library.hcmue.edu.vn bằng tài khoản sinh viên.', 'general', '2026-05-01', '2026-12-31', 1, 1),
('Nghỉ lễ 30/4 - 1/5',                    'Thư viện nghỉ lễ từ 30/4 đến 1/5/2026. Sách đến hạn trong ngày lễ được gia hạn tự động đến hết ngày 2/5/2026.', 'holiday', '2026-04-30', '2026-05-01', 0, 1),
('Tặng sách đầu năm học mới',              'Nhân dịp đầu năm học mới 2025-2026, thư viện tặng 2 phiếu mượn miễn phí cho sinh viên năm nhất. Nhận tại quầy thư viện từ 1-15/9.', 'general', '2026-09-01', '2026-09-15', 1, 1),
('Giới thiệu sách mới: Bộ Haruki Murakami','Thư viện vừa nhập bộ sách Haruki Murakami gồm "Rừng Na-uy", "Kafka bên bờ biển" và nhiều tựa khác. Hãy đặt mượn ngay!', 'general', '2026-05-10', '2026-06-10', 1, 1),
('Hướng dẫn sử dụng thư viện cho SV mới', 'Sinh viên năm nhất tham gia buổi hướng dẫn sử dụng thư viện vào 8:00 ngày 5/9/2026 tại phòng 101, tầng 1.', 'event', '2026-09-05', '2026-09-05', 1, 1),
('Kết quả cuộc thi đọc sách tháng 4',     'Xin chúc mừng các bạn đoạt giải cuộc thi đọc sách tháng 4/2026. Xem danh sách chi tiết tại bảng tin thư viện và website.', 'contest', '2026-05-01', '2026-05-10', 0, 1),
('Sách giáo trình học kỳ 2 đã có đủ',     'Toàn bộ giáo trình học kỳ 2 năm 2025-2026 đã được nhập về đầy đủ. Sinh viên có thể đến mượn từ ngày 28/5/2026.', 'general', '2026-05-28', '2026-08-30', 1, 1),
('Thông báo thay đổi giờ mở cửa',         'Kể từ ngày 1/6/2026, thư viện sẽ mở cửa từ 7:00 (thay vì 7:30) để phục vụ sinh viên ôn thi học kỳ.', 'general', '2026-06-01', '2026-07-31', 1, 1),
('Dịch vụ scan tài liệu miễn phí',        'Thư viện cung cấp dịch vụ scan tài liệu miễn phí (tối đa 20 trang/lần) tại quầy dịch vụ tầng 1 cho sinh viên và giảng viên.', 'general', '2026-05-01', '2026-12-31', 1, 1),
('Tổng kết hoạt động thư viện Q1/2026',   'Báo cáo hoạt động thư viện quý 1/2026: 850 lượt mượn sách, 320 sinh viên mới đăng ký thẻ, 120 đầu sách mới được bổ sung.', 'general', '2026-04-10', '2026-04-30', 0, 1);

