INSERT INTO support_tickets (user_id, category, title, description, status) VALUES
(2,  'card_issue',   'Yêu cầu mở khóa thẻ thư viện',           'Thẻ của em bị khóa nhưng em đã trả hết sách quá hạn rồi ạ. Mong thầy cô hỗ trợ kiểm tra mở khóa giúp em.', 'open'),
(3,  'damaged_book', 'Báo cáo sách bị rách trang',              'Cuốn sách Dế Mèn phiêu lưu ký em vừa mượn có một số trang bị rách ở chương 3. Em muốn báo cáo trước để tránh bị phạt khi trả.', 'closed'),
(4,  'lost_item',    'Làm mất sách Tuổi thơ dữ dội',            'Em sơ suất làm mất cuốn sách trong quá trình mượn. Em muốn hỏi thủ tục bồi thường hoặc mua đền thế nào ạ?', 'in_progress'),
(5,  'other',        'Hỏi về thời gian mượn tối đa',            'Em muốn hỏi một lần em được mượn tối đa bao nhiêu cuốn và thời hạn mượn tối đa là bao lâu ạ?', 'closed'),
(6,  'card_issue',   'Không đăng nhập được tài khoản',          'Em bị quên mật khẩu tài khoản thư viện, thử reset qua email nhưng không nhận được email. Nhờ thầy hỗ trợ ạ.', 'closed'),
(7,  'damaged_book', 'Sách mượn bị ẩm mốc',                     'Cuốn sách Clean Code em mượn bị ẩm ở một góc, có vẻ do bảo quản không tốt. Em không làm hỏng ạ.', 'open'),
(8,  'lost_item',    'Mất thẻ thư viện',                        'Em làm mất thẻ thư viện trong lúc đi học. Em cần làm lại thẻ mới thì thủ tục như thế nào ạ?', 'in_progress'),
(9,  'other',        'Yêu cầu thêm sách CNTT',                  'Em kiến nghị thư viện bổ sung thêm sách về DevOps, Docker, Kubernetes vì hiện tại mảng này còn thiếu nhiều.', 'open'),
(10, 'card_issue',   'Lỗi hệ thống khi đăng nhập',              'Khi em đăng nhập hiển thị thông báo lỗi "Internal Server Error". Em đã thử trên nhiều trình duyệt khác nhau.', 'closed'),
(11, 'damaged_book', 'Phát hiện sách viết vào',                  'Cuốn Đắc nhân tâm em mượn có ai đó viết và gạch chân khắp nơi. Em muốn báo cáo để thư viện xem xét.', 'closed'),
(12, 'other',        'Đề xuất mở rộng giờ phục vụ',             'Em kiến nghị thư viện mở cửa đến 22:00 trong mùa thi vì nhiều bạn học buổi tối không kịp đến mượn sách.', 'open'),
(13, 'lost_item',    'Quên đồ vật trong khu đọc sách',           'Em có để quên một cái ví tiền trong khu đọc sách tầng 2 vào chiều hôm qua. Nhờ thầy kiểm tra giúp ạ.', 'closed'),
(14, 'card_issue',   'Thẻ bị khóa vì không trả sách đúng hạn', 'Thẻ em bị khóa vì trả sách trễ 3 ngày. Em đã trả sách rồi, nhờ thầy mở khóa thẻ để em có thể mượn sách cho kỳ thi.', 'in_progress'),
(15, 'damaged_book', 'Sách thiếu trang',                         'Cuốn Sapiens em mượn bị thiếu trang 120-135. Em không biết trước khi mượn. Nhờ thư viện kiểm tra lại.', 'open'),
(16, 'other',        'Hỏi về dịch vụ đặt mượn trước',           'Thư viện có hỗ trợ đặt mượn sách trước không ạ? Vì có những cuốn em cần nhưng hay hết.', 'closed'),
(17, 'card_issue',   'Không thể gia hạn mượn sách online',      'Em muốn gia hạn mượn sách trên hệ thống nhưng bấm nút gia hạn không thấy phản hồi gì ạ.', 'in_progress'),
(18, 'lost_item',    'Mất sách Atomic Habits',                   'Em không tìm được cuốn Atomic Habits em mượn từ tháng trước. Có thể đã để quên đâu đó. Nhờ hỗ trợ thủ tục đền bù.', 'open'),
(19, 'damaged_book', 'Bìa sách bị rách',                         'Cuốn Nhà giả kim em mượn bị rách bìa sau. Em muốn báo cáo để không bị tính phí khi trả ạ.', 'closed'),
(20, 'other',        'Kiến nghị trang bị thêm máy tính',        'Khu đọc sách tầng 3 hiện chỉ có 5 máy tính, thường xuyên hết chỗ. Em kiến nghị bổ sung thêm ít nhất 5 máy nữa.', 'open'),
(21, 'card_issue',   'Email xác nhận đăng ký không nhận được', 'Em vừa đăng ký tài khoản thư viện nhưng không nhận được email xác nhận. Hộp thư spam cũng không có ạ.', 'closed'),
(22, 'damaged_book', 'Sách Rừng Na-uy bị ố vàng nhiều trang',  'Em mượn cuốn Rừng Na-uy nhưng thấy sách bị ố vàng rất nhiều trang, có mùi ẩm mốc. Mong thư viện xem xét.', 'open'),
(23, 'other',        'Hỏi về chính sách kéo dài thẻ thư viện', 'Thẻ thư viện của em sắp hết hạn vào cuối tháng 6. Em cần làm gì để gia hạn thẻ ạ?', 'in_progress'),
(24, 'lost_item',    'Mất cặp sách trong thư viện',              'Em bị mất một chiếc cặp sách màu đen khi đang đọc sách ở tầng 1. Trong cặp có nhiều tài liệu quan trọng.', 'open'),
(25, 'card_issue',   'Tài khoản bị khóa không rõ lý do',        'Tài khoản của em đột ngột bị khóa dù em không vi phạm gì. Mong thầy kiểm tra và mở khóa giúp em.', 'closed'),
(26, 'other',        'Đề xuất bổ sung sách tiếng Nhật',          'Em học tiếng Nhật và thấy thư viện còn rất thiếu sách tiếng Nhật. Em kiến nghị bổ sung thêm giáo trình JLPT N5-N2.', 'open'),
(27, 'damaged_book', 'Sách bị nhòe mực nhiều chỗ',               'Cuốn Người đua diều em mượn bị nhòe mực ở nhiều trang, không đọc được một số đoạn. Nhờ thư viện kiểm tra lại.', 'in_progress'),
(28, 'other',        'Hỏi về cách tra cứu sách online',          'Em muốn hỏi thư viện có hệ thống tra cứu sách online không ạ? Mình không biết sách nào đang có sẵn.', 'closed'),
(29, 'card_issue',   'Quên tên đăng nhập tài khoản',             'Em không nhớ tên đăng nhập tài khoản thư viện. Em chỉ nhớ địa chỉ email đăng ký. Nhờ thầy hỗ trợ.', 'closed'),
(30, 'lost_item',    'Mất sách Mắt biếc khi đang đọc ngoài',    'Em đem sách Mắt biếc ra ngoài đọc và bị mất. Em muốn hỏi thủ tục và mức phí bồi thường sách ạ.', 'in_progress'),
(31, 'damaged_book', 'Phát hiện ghi chú viết tay trong sách',   'Trong cuốn Đất rừng phương Nam em mượn có rất nhiều ghi chú viết tay của người mượn trước. Mong thư viện xử lý.', 'open');

-- ═══════════════════════════════════════════════════════════════════════
-- 8. TICKET_MESSAGES — 60 tin nhắn hỗ trợ
-- ═══════════════════════════════════════════════════════════════════════
INSERT INTO ticket_messages (ticket_id, sender_id, sender_role, message) VALUES
-- Ticket 2: Báo cáo sách bị rách trang (closed)
(2, 3,  'user',  'Em muốn báo cáo sách bị rách trang ạ. Trang 45-48 bị rách góc, dường như là của người mượn trước.'),
(2, 1,  'admin', 'Chào em, thầy đã ghi nhận. Sách này bị rách từ trước khi em mượn nên em không bị phạt. Cứ yên tâm đọc và trả đúng hạn nhé.'),
(2, 3,  'user',  'Dạ em cảm ơn thầy nhiều ạ! Em sẽ giữ gìn cẩn thận và trả đúng hạn.'),
(2, 1,  'admin', 'Tốt lắm em! Sau khi em trả, thư viện sẽ xử lý sách này. Ticket này được đóng nhé.'),
-- Ticket 4: Hỏi về thời gian mượn (closed)
(4, 5,  'user',  'Thầy ơi cho em hỏi thư viện cho mượn tối đa mấy cuốn một lần ạ?'),
(4, 1,  'admin', 'Chào em, mỗi sinh viên được mượn tối đa 3 cuốn cùng lúc, thời hạn mượn 14 ngày. Có thể gia hạn thêm 7 ngày nếu chưa có người khác đặt mượn.'),
(4, 5,  'user',  'Dạ em cảm ơn thầy ạ! Vậy nếu sách đang có người mượn thì em có thể đặt trước không ạ?'),
(4, 1,  'admin', 'Hiện tại hệ thống chưa hỗ trợ đặt trước. Em có thể quay lại kiểm tra định kỳ hoặc hỏi trực tiếp tại quầy. Chúng tôi sẽ phát triển tính năng này sớm!'),
(4, 5,  'user',  'Dạ vâng, em hiểu rồi ạ. Cảm ơn thầy!'),
-- Ticket 5: Không đăng nhập được (closed)
(5, 6,  'user',  'Thầy ơi em bị quên mật khẩu, thử reset qua email nhưng không nhận được.'),
(5, 1,  'admin', 'Chào em, em có thể cung cấp địa chỉ email đăng ký tài khoản cho thầy được không?'),
(5, 6,  'user',  'Dạ email của em là student6@library.local ạ.'),
(5, 1,  'admin', 'Thầy đã kiểm tra và thấy email của em chính xác. Thầy đã reset mật khẩu tạm thời là "Temp@12345", em đăng nhập và đổi mật khẩu mới ngay nhé!'),
(5, 6,  'user',  'Dạ em đăng nhập được rồi ạ! Cảm ơn thầy rất nhiều!'),
-- Ticket 7: Mất thẻ thư viện (in_progress)
(7, 8,  'user',  'Thầy ơi em bị mất thẻ thư viện, cần làm lại. Thủ tục như thế nào ạ?'),
(7, 1,  'admin', 'Chào em. Để làm lại thẻ thư viện em cần: 1) Ảnh thẻ sinh viên, 2) Đơn xin làm lại thẻ (lấy tại quầy), 3) Lệ phí 20,000đ. Em đến trực tiếp thư viện nhé.'),
(7, 8,  'user',  'Dạ em hiểu rồi ạ. Em sẽ đến vào sáng mai. Cho em hỏi thêm là mất thẻ có ảnh hưởng đến lịch sử mượn sách không ạ?'),
(7, 1,  'admin', 'Không em nhé, lịch sử mượn sách được lưu trong hệ thống theo tài khoản, không phải thẻ vật lý. Em cứ yên tâm.'),
-- Ticket 10: Phát hiện sách viết vào (closed)
(10, 11, 'user',  'Thầy ơi cuốn Đắc nhân tâm em mượn có người viết và gạch chân khắp nơi ạ.'),
(10, 1,  'admin', 'Chào em, cảm ơn đã báo cáo. Thư viện ghi nhận và sẽ xử lý sách này sau khi em trả. Em không bị phạt trong trường hợp này.'),
(10, 11, 'user',  'Dạ em cảm ơn thầy! Vậy khi trả em có cần ghi chú gì không ạ?'),
(10, 1,  'admin', 'Không cần em nhé. Chỉ cần trả sách và thông báo với nhân viên về tình trạng này là được.'),
-- Ticket 13: Thẻ bị khóa (in_progress)
(13, 14, 'user',  'Thầy ơi em bị khóa thẻ vì trả sách trễ 3 ngày. Em đã trả xong rồi, nhờ thầy mở khóa giúp ạ.'),
(13, 1,  'admin', 'Chào em. Thầy đã kiểm tra và xác nhận em đã trả sách. Thầy đang xử lý mở khóa cho em, chờ thầy chút nhé.'),
(13, 14, 'user',  'Dạ vâng ạ, cảm ơn thầy! Em cần mượn sách gấp để ôn thi ạ.'),
(13, 1,  'admin', 'Thầy hiểu rồi em. Do trả trễ nên phải có quy trình xử lý mất vài giờ. Thầy sẽ ưu tiên xử lý ngay trong hôm nay.'),
-- Ticket 16: Không thể gia hạn (in_progress)
(16, 17, 'user',  'Thầy ơi em bấm nút gia hạn sách trên hệ thống nhưng không có phản hồi gì.'),
(16, 1,  'admin', 'Chào em, cảm ơn đã phản ánh. Có thể do lỗi kỹ thuật. Em thử xóa cache trình duyệt và thử lại xem sao nhé.'),
(16, 17, 'user',  'Em đã thử nhiều trình duyệt khác nhau rồi nhưng vẫn không được ạ.'),
(16, 1,  'admin', 'Thầy đã ghi nhận và sẽ báo bộ phận kỹ thuật xử lý. Em có thể đến quầy thư viện để gia hạn trực tiếp trong lúc chờ. Xin lỗi vì sự bất tiện này!'),
-- Ticket 22: Hỏi gia hạn thẻ (in_progress)
(22, 23, 'user',  'Thầy ơi thẻ thư viện của em sắp hết hạn vào cuối tháng 6. Em cần làm gì để gia hạn ạ?'),
(22, 1,  'admin', 'Chào em, để gia hạn thẻ thư viện em chỉ cần đến quầy thư viện với thẻ sinh viên còn hiệu lực. Thẻ thư viện được gia hạn miễn phí theo năm học.'),
(22, 23, 'user',  'Dạ vậy nếu thẻ sinh viên chưa được gia hạn thì sao ạ? Em đang chờ nhà trường cấp thẻ mới.'),
(22, 1,  'admin', 'Trong trường hợp này, em có thể dùng giấy xác nhận sinh viên còn hiệu lực từ phòng đào tạo thay thế. Ticket này để mở để theo dõi nhé!'),
-- Ticket 27: Sách bị nhòe mực (in_progress)
(27, 27, 'user',  'Thầy ơi cuốn Người đua diều em mượn bị nhòe mực nhiều trang, không đọc được.'),
(27, 1,  'admin', 'Chào em, cảm ơn đã báo cáo. Thầy sẽ kiểm tra sách này ngay khi em trả. Em không bị tính phí do lỗi này không phải từ em.'),
(27, 27, 'user',  'Dạ em cảm ơn thầy! Vậy em có thể mượn cuốn khác để thay thế đọc tạm không ạ?'),
(27, 1,  'admin', 'Tất nhiên em! Em đến quầy và nói với nhân viên, chúng tôi sẽ hỗ trợ em tìm cuốn sách phù hợp.'),
-- Ticket 30: Mất sách Mắt biếc (in_progress)
(30, 30, 'user',  'Thầy ơi em đã làm mất cuốn Mắt biếc. Em phải bồi thường như thế nào ạ?'),
(30, 1,  'admin', 'Chào em. Đối với sách bị mất, em cần bồi thường bằng cách mua cuốn sách tương đương (cùng tên, cùng nhà xuất bản) hoặc đền tiền theo giá bìa nhân 1.5 lần.'),
(30, 30, 'user',  'Dạ vậy cuốn Mắt biếc giá bìa là bao nhiêu ạ? Em cần biết để chuẩn bị tiền.'),
(30, 1,  'admin', 'Giá bìa cuốn Mắt biếc NXB Trẻ 2019 là 59,000đ. Mức bồi thường là 59,000 x 1.5 = 88,500đ. Hoặc em mua cuốn sách mới cùng phiên bản đem nộp cũng được.'),
(30, 30, 'user',  'Dạ em sẽ mua cuốn mới nộp cho thư viện ạ. Cảm ơn thầy đã giải đáp chi tiết!'),
-- Thêm tin nhắn cho ticket 1 (mở khóa thẻ)
(1, 2,  'user',  'Thầy ơi em đã trả hết sách quá hạn từ tháng trước rồi. Sao thẻ em vẫn bị khóa ạ?'),
(1, 1,  'admin', 'Chào em Nguyễn Văn An. Thầy sẽ kiểm tra lại hệ thống. Em cho thầy biết cuốn sách nào em đã trả để thầy xác nhận nhé.'),
(1, 2,  'user',  'Dạ em đã trả cuốn "Chí Phèo" và "Lão Hạc" vào ngày 14/5 ạ. Em có biên nhận tại quầy.'),
(1, 1,  'admin', 'Thầy đã xác nhận giao dịch trả sách của em rồi. Thầy sẽ chuyển yêu cầu mở khóa lên quản trị viên hệ thống. Chờ thầy 24 giờ nhé.');

-- ═══════════════════════════════════════════════════════════════════════
-- 9. CHAT_LOGS — 50 cuộc hội thoại chatbot đa dạng
-- ═══════════════════════════════════════════════════════════════════════
INSERT INTO chat_logs (user_id, message, response) VALUES
(2,    'Làm thế nào để mượn sách?',                  'Chào bạn! Để mượn sách, bạn hãy: 1) Đăng nhập vào tài khoản, 2) Tìm kiếm sách muốn mượn, 3) Nhấn nút "Mượn sách". Thủ thư sẽ duyệt trong vòng 24 giờ làm việc.'),
(NULL, 'Giờ mở cửa của thư viện?',                   'Thư viện HCMUE mở cửa từ 7:30 đến 21:00 tất cả các ngày trong tuần (trừ ngày lễ Tết). Mùa hè và mùa thi có thể điều chỉnh giờ. Rất hân hạnh được phục vụ bạn!'),
(3,    'Tìm sách về lập trình PHP',                  'Thư viện đang có: "Lập trình PHP căn bản" (5 quyển - còn mượn được). Ngoài ra còn có "Clean Code" và "Design Patterns" rất phù hợp cho lập trình viên PHP!'),
(4,    'Sách của Nam Cao có những cuốn nào?',        'Thư viện đang có 2 tác phẩm của Nam Cao: "Chí Phèo" (4 quyển, đang available) và "Lão Hạc" (3 quyển, available). Cả hai đều là tác phẩm văn học Việt Nam kinh điển.'),
(5,    'Tôi muốn tìm sách kỹ năng sống',             'Thư viện có nhiều sách kỹ năng sống hay: "Đắc nhân tâm", "Cà phê cùng Tony", "Tuổi trẻ đáng giá bao nhiêu", "Bí mật tư duy triệu phú", "Atomic Habits". Bạn muốn mượn cuốn nào?'),
(6,    'Thư viện có sách Murakami không?',           'Có ạ! Thư viện đang có: "Kafka bên bờ biển" (3 quyển), "Rừng Na-uy" (4 quyển). Cả hai đều là kiệt tác của Haruki Murakami, bạn nên đọc thử!'),
(7,    'Tôi cần gia hạn sách đang mượn',             'Để gia hạn sách, bạn vào mục "Lịch sử mượn" trong tài khoản, chọn sách muốn gia hạn và nhấn "Gia hạn". Thời gian gia hạn tối đa là 7 ngày nếu sách chưa có người khác đặt.'),
(8,    'Làm sao để trả sách?',                       'Để trả sách, bạn đến trực tiếp quầy thư viện mang theo sách cần trả. Nhân viên sẽ kiểm tra và xác nhận. Hoặc bạn cũng có thể để vào thùng trả sách 24/7 tại cổng thư viện.'),
(9,    'Sách Python có không?',                      'Có! Thư viện đang có: "Python Crash Course" (4 quyển) và "Automate the Boring Stuff with Python" (3 quyển). Phù hợp cho người mới học Python lẫn người đã có kinh nghiệm.'),
(10,   'Thư viện có sách về machine learning không?','Có ạ! Thư viện có: "Machine Learning cơ bản" của thầy Vũ Hữu Tiệp (4 quyển, tiếng Việt rất hay!) và "Deep Learning với Python" của François Chollet (3 quyển).'),
(11,   'Tôi muốn đọc sách về sức khỏe',             'Thư viện có nhiều sách sức khỏe tốt: "Cẩm nang y học gia đình", "Yoga và thiền định", "Ngủ đúng cách", "Chạy bộ vì sức khỏe", "Bí quyết sống 100 tuổi". Bạn quan tâm thể loại nào?'),
(12,   'Sách gì hay cho người mới ra trường?',       'Thầy gợi ý bạn một số cuốn phù hợp: "Tuổi trẻ đáng giá bao nhiêu", "Atomic Habits", "7 Thói quen của người thành đạt", "Không bao giờ là thất bại". Chúc bạn thành công!'),
(13,   'Thư viện có bán sách không?',                'Thư viện HCMUE không bán sách, chỉ cho mượn. Tuy nhiên, thư viện có thể hỗ trợ bạn thông tin về các nhà sách gần trường. Bạn muốn mượn sách nào?'),
(14,   'Mượn sách tối đa bao nhiêu ngày?',           'Thời hạn mượn tiêu chuẩn là 14 ngày. Bạn có thể gia hạn thêm 1 lần tối đa 7 ngày nếu sách chưa được người khác đặt. Trong mùa thi, thư viện thường gia hạn thêm 7 ngày tự động.'),
(15,   'Tìm sách triết học',                         'Thư viện có các sách triết học: "Triết học nhập môn" (Bertrand Russell), "Đạo đức học Nicomachean" (Aristotle), "Cộng hòa" (Plato), "Đạo đức kinh" (Lão Tử), "Thiền luận" (Suzuki).'),
(16,   'Sách nào hay nhất thư viện?',                'Theo thống kê lượt mượn nhiều nhất, các sách hot nhất là: 1. Sapiens, 2. Atomic Habits, 3. Đắc nhân tâm, 4. Nhà giả kim, 5. Machine Learning cơ bản. Bạn thử đọc nhé!'),
(17,   'Cách đặt lại mật khẩu?',                    'Để đặt lại mật khẩu: vào trang đăng nhập, nhấn "Quên mật khẩu", nhập địa chỉ email đăng ký, kiểm tra email để nhận link đặt lại mật khẩu. Nếu không nhận được email, hãy liên hệ quầy thư viện.'),
(18,   'Sách Nguyễn Nhật Ánh có những cuốn nào?',   'Thư viện đang có của Nguyễn Nhật Ánh: "Mắt biếc", "Cho tôi xin một vé đi tuổi thơ", "Cô gái đến từ hôm qua", "Ngồi khóc trên cây", "Tôi thấy hoa vàng trên cỏ xanh". Rất nhiều lựa chọn cho bạn!'),
(19,   'Thủ tục đăng ký thẻ thư viện mới?',        'Để đăng ký thẻ thư viện: 1) Đến quầy thư viện với thẻ sinh viên, 2) Điền form đăng ký, 3) Chụp ảnh hoặc nộp ảnh 3x4, 4) Nhận thẻ trong ngày. Hoàn toàn miễn phí cho sinh viên HCMUE!'),
(20,   'Tìm sách lịch sử Việt Nam',                 'Thư viện có sách lịch sử VN: "Quốc sử diễn ca" (Lê Ngô Cát), "Lịch sử Việt Nam bằng tranh" (bộ sách tranh sinh động). Ngoài ra có "Sapiens" và "Homo Deus" về lịch sử thế giới.'),
(21,   'Thư viện có wifi không?',                   'Có ạ! Thư viện HCMUE có wifi miễn phí cho sinh viên. Tên mạng: HCMUE-Library, mật khẩu lấy tại quầy thư viện bằng thẻ sinh viên. Tốc độ ổn định để phục vụ nghiên cứu.'),
(22,   'Tôi muốn tìm sách về yoga',                 'Thư viện có "Yoga và thiền định" của B.K.S. Iyengar, được đánh giá cao về nội dung và hình ảnh minh họa. Ngoài ra còn có "Thiền và khoa học về não bộ" nếu bạn muốn hiểu thêm về khoa học thiền.'),
(23,   'Sách nào phù hợp cho sinh viên năm nhất?', 'Cho SV năm 1 thầy gợi ý: "Phương pháp học tập của người giỏi", "Bí quyết học tốt", "Atomic Habits", "Cà phê cùng Tony", "Tuổi trẻ đáng giá bao nhiêu". Sẽ rất hữu ích!'),
(24,   'Thư viện có sách tiếng Anh không?',         'Có ạ! Thư viện có nhiều sách tiếng Anh: "Clean Code", "Design Patterns", "Python Crash Course", "To Kill a Mockingbird", "The Pragmatic Programmer"... và nhiều hơn nữa.'),
(25,   'Làm sao để viết review sách?',              'Để viết review sách, bạn cần: 1) Đã mượn cuốn sách đó, 2) Đăng nhập tài khoản, 3) Vào trang chi tiết sách, 4) Kéo xuống phần "Đánh giá" và điền nhận xét cùng số sao.'),
(26,   'Tìm sách của Paulo Coelho',                 'Thư viện hiện có "Nhà giả kim" (Paulo Coelho, 6 quyển). Đây là cuốn sách bán chạy và được đánh giá rất cao, bạn nên đọc thử!'),
(27,   'Sách về dinh dưỡng và ăn uống có không?',  'Có ạ! Thư viện có: "Dinh dưỡng và sức khỏe" (Từ Giấy), "Ăn gì để không bị bệnh" (Joel Fuhrman), "Nghệ thuật nấu ăn Việt Nam" (Bùi Kim Điền). Rất đầy đủ!'),
(28,   'Thư viện có in tài liệu không?',            'Thư viện có dịch vụ photo/in tài liệu với giá ưu đãi cho sinh viên HCMUE. Ngoài ra còn có dịch vụ scan miễn phí 20 trang/lần. Bạn đến quầy dịch vụ tầng 1 để sử dụng.'),
(29,   'Tìm sách về kinh doanh startup',            'Thư viện có nhiều sách startup hay: "Quốc gia khởi nghiệp" (Dan Senor), "Zero to One" (Peter Thiel), "The Lean Startup" (Eric Ries), "Khởi nghiệp từ 100 USD" (Chris Guillebeau).'),
(30,   'Sách Sapiens còn không?',                   '"Sapiens: Lược sử loài người" hiện có 4 quyển trong thư viện. Đây là sách cực kỳ nổi tiếng nên mượn sớm nhé! Ngoài ra còn có "Homo Deus" và "21 bài học cho thế kỷ 21" của cùng tác giả.'),
(31,   'Làm sao biết sách có sẵn không?',          'Bạn có thể kiểm tra trạng thái sách trực tiếp trên hệ thống. Vào mục "Tìm kiếm sách", tìm tên sách muốn mượn, sẽ thấy thông tin "available" (có sẵn) hoặc "borrowed" (đang được mượn).'),
(32,   'Thư viện có sách tiếng Nhật không?',       'Hiện tại thư viện chưa có nhiều sách tiếng Nhật. Bạn có thể gửi kiến nghị bổ sung qua hệ thống ticket hỗ trợ, chúng tôi sẽ xem xét trong kế hoạch nhập sách tiếp theo!'),
(33,   'Sách khoa học phổ thông có gì?',           'Thư viện có: "Vật lý học vui" (Perelman), "Vũ trụ trong vỏ hạt dẻ" (Hawking), "Lược sử thời gian" (Hawking), "Hóa học quanh ta", "Thiên văn học đại cương", "Bách khoa toàn thư khoa học".'),
(34,   'Tôi cần sách về tâm lý học',               'Thư viện có nhiều sách tâm lý: "Phân tâm học nhập môn" (Freud), "Tâm lý học đám đông" (Le Bon), "Bẫy tư duy" (Kahneman), "Sức mạnh của hiện tại" (Tolle), "Sơ cứu tâm lý" (Winch).'),
(35,   'Sách nào về lịch sử thế giới?',           'Thư viện có: "Sapiens" và "Homo Deus" của Harari (lịch sử nhân loại từ quá khứ đến tương lai), "Chiến tranh và hòa bình" (Tolstoy), "Những người khốn khổ" (Hugo) phản ánh lịch sử xã hội.'),
(NULL, 'Thư viện ở đâu?',                           'Thư viện HCMUE nằm ở tòa nhà B, tầng 1-3, số 280 An Dương Vương, Phường 4, Quận 5, TP. Hồ Chí Minh. Mở cửa từ 7:30 đến 21:00 mỗi ngày (trừ lễ Tết).'),
(NULL, 'Điện thoại của thư viện?',                  'Bạn có thể liên hệ thư viện qua số điện thoại: (028) 3835 7777 hoặc email: library@hcmue.edu.vn. Chúng tôi luôn sẵn sàng hỗ trợ bạn!'),
(36,   'Sách về toán học có gì?',                   'Thư viện có: "Toán học và đời sống" (Chu Văn Mẫn), "Toán học lớp 12", "Introduction to Algorithms" (Cormen, cho sinh viên CNTT). Bạn cần loại sách toán nào?'),
(37,   'Tìm sách của Stephen Hawking',             'Thư viện có 2 cuốn của Stephen Hawking: "Vũ trụ trong vỏ hạt dẻ" (3 quyển) và "Lược sử thời gian" (2 quyển). Cả hai đều giải thích vũ trụ theo cách rất hấp dẫn!'),
(38,   'Sách nào về phát triển cá nhân tốt nhất?', 'Top 5 sách phát triển cá nhân được mượn nhiều nhất: 1. Atomic Habits, 2. Đắc nhân tâm, 3. 7 Thói quen người thành đạt, 4. Ikigai, 5. Mindset. Thầy gợi ý bắt đầu với Atomic Habits!'),
(39,   'Thư viện có phòng học nhóm không?',        'Thư viện có 5 phòng học nhóm từ 4-8 người ở tầng 3, đặt chỗ miễn phí tại quầy hoặc online (tính năng đặt trước online sắp ra mắt). Thời gian tối đa 3 giờ/lần.'),
(40,   'Tôi cần sách ôn thi tiếng Anh',            'Thư viện có: "Ôn thi TOEIC 600+" (5 quyển) và "Tiếng Anh giao tiếp hàng ngày" (6 quyển). Cả hai rất phổ biến với sinh viên đang ôn thi chứng chỉ.'),
(41,   'Sách lập trình Java có không?',            'Hiện tại thư viện chưa có sách chuyên về Java. Nhưng có "Design Patterns", "Clean Code" và "The Pragmatic Programmer" rất hữu ích cho lập trình viên Java. Hãy gửi kiến nghị bổ sung sách Java!'),
(42,   'Tìm sách về đạo Phật',                     'Thư viện có: "Bước đầu học Phật" (Thích Nhất Hạnh), "Sống trong từng khoảnh khắc" (Thích Nhất Hạnh), "Thiền luận" (Suzuki), "Thiền và khoa học về não bộ". Bạn muốn tìm hiểu theo hướng nào?'),
(43,   'Cách tìm kiếm sách trên hệ thống?',        'Bạn có thể tìm sách theo: 1) Tên sách, 2) Tác giả, 3) Thể loại/Danh mục. Vào trang "Danh sách sách" và dùng thanh tìm kiếm hoặc bộ lọc bên trái để lọc theo tiêu chí mong muốn.'),
(44,   'Sách Dostoevsky có không?',                'Có! Thư viện có "Tội ác và hình phạt" (3 quyển). Đây là kiệt tác về tâm lý con người. Thư viện cũng đang xem xét nhập thêm "Anh em nhà Karamazov".'),
(45,   'Sách về dinh dưỡng thể thao',             'Thư viện có "Chạy bộ vì sức khỏe" phù hợp cho người luyện tập thể thao. Về dinh dưỡng có "Ăn gì để không bị bệnh" và "Dinh dưỡng và sức khỏe". Bạn muốn tìm sách cụ thể hơn?'),
(NULL, 'Thư viện tầng mấy?',                       'Thư viện nằm ở tầng 1-3 tòa nhà B. Tầng 1: quầy phục vụ, tra cứu và mượn-trả sách. Tầng 2: khu đọc sách yên tĩnh. Tầng 3: phòng học nhóm và khu máy tính.'),
(46,   'Có sách về Erasmus, Nietzsche không?',     'Hiện tại thư viện chưa có sách riêng về Erasmus hay Nietzsche. Nhưng "Triết học nhập môn" (Bertrand Russell) có đề cập nhiều triết gia nổi tiếng. Bạn gửi kiến nghị bổ sung nhé!'),
(47,   'Sách văn học Nga có gì?',                  'Thư viện có sách văn học Nga: "Tội ác và hình phạt" (Dostoevsky), "Chiến tranh và hòa bình" (Tolstoy), "Anna Karenina" (Tolstoy). Đây đều là những kiệt tác bất hủ của văn học Nga!'),
(48,   'Mượn sách quá hạn phải làm gì?',          'Nếu sách quá hạn, bạn cần trả sách càng sớm càng tốt để tránh tài khoản bị khóa. Có thể có khoản phạt tùy theo chính sách của thư viện. Liên hệ quầy thư viện để được hỗ trợ xử lý.'),
(49,   'Sách về lập trình web có không?',          'Thư viện có "Lập trình PHP căn bản" cho backend web. Cho frontend có "JavaScript: The Good Parts" và "You Don\'t Know JS". Đang xem xét nhập thêm sách về React, Vue.js.'),
(50,   'Thư viện có hệ thống tự động không?',     'Thư viện HCMUE có hệ thống quản lý trực tuyến hiện đại: tìm kiếm sách, đặt mượn, gia hạn và theo dõi lịch sử mượn online. Hệ thống chatbot AI này cũng là một phần của nỗ lực số hóa!');

